import{_ as t,o,c as a,ak as r}from"./chunks/framework.BNVJvTzl.js";const g=JSON.parse('{"title":"Projects & Types","description":"The four project types in VERA and how each one determines when and how revenue is recognized.","frontmatter":{"description":"The four project types in VERA and how each one determines when and how revenue is recognized."},"headers":[],"relativePath":"reference/concepts/projects.md","filePath":"reference/concepts/projects.md"}'),n={name:"reference/concepts/projects.md"};function s(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="projects-types" tabindex="-1">Projects &amp; Types <a class="header-anchor" href="#projects-types" aria-label="Permalink to &quot;Projects &amp; Types&quot;">​</a></h1><p>Every piece of work in VERA lives inside a project. A project has a type, a client, and a budget. The type determines how VERA calculates revenue.</p><hr><h2 id="project-types" tabindex="-1">Project types <a class="header-anchor" href="#project-types" aria-label="Permalink to &quot;Project types&quot;">​</a></h2><p>VERA supports T&amp;M, Fixed Price, Pro Bono, Internal, and Retainer for new projects. <strong>The type must always be specified when creating a project — VERA will never assume a default.</strong></p><blockquote><p><strong>Note:</strong> Agile is not currently available for new projects. Existing Agile projects continue to work — they can be viewed, reported on, and managed. Only creation of new ones is blocked. Retainer&#39;s own creation was reinstated on 2026-09-23 — maintenance retainers are ordinary for the agencies VERA serves, and Agile has no comparable demand, so only Agile stays frozen.</p></blockquote><h3 id="t-m-time-materials" tabindex="-1">T&amp;M (Time &amp; Materials) <a class="header-anchor" href="#t-m-time-materials" aria-label="Permalink to &quot;T&amp;M (Time &amp; Materials)&quot;">​</a></h3><p>Bill as you go. Revenue is calculated from logged hours.</p><ul><li><strong>Budget</strong>: total project hours</li><li><strong>Revenue</strong>: <code>hours_logged × billing_rate</code></li><li><strong>Billing model</strong>: per-entry accrual</li><li><strong>Work gate</strong>: stop work when <code>hours_budget</code> is exhausted</li><li><strong>Use case</strong>: open-scope work where effort is unpredictable</li></ul><blockquote><p>&quot;Create project Nike Campaign as T&amp;M&quot;</p></blockquote><hr><h3 id="fixed-price" tabindex="-1">Fixed Price <a class="header-anchor" href="#fixed-price" aria-label="Permalink to &quot;Fixed Price&quot;">​</a></h3><p>A flat contract for a defined scope. Revenue accrues as work is completed.</p><ul><li><strong>Budget</strong>: total project hours (the effort estimate)</li><li><strong>Contract value</strong>: the agreed price in dollars</li><li><strong>Revenue</strong>: <code>(hours_logged ÷ hours_budget) × contract_value</code> — capped at 100%</li><li><strong>Billing model</strong>: percentage-of-completion</li><li><strong>Work gate</strong>: stop work when <code>hours_budget</code> is exhausted</li><li><strong>Use case</strong>: scoped deliverables with a negotiated price</li></ul><blockquote><p>&quot;Create project Nike Rebrand as Fixed Price for $50,000 with 200 hour budget&quot;</p></blockquote><hr><h3 id="pro-bono" tabindex="-1">Pro Bono <a class="header-anchor" href="#pro-bono" aria-label="Permalink to &quot;Pro Bono&quot;">​</a></h3><p>Free work. Hours are tracked but no revenue is recognized.</p><ul><li><strong>Budget</strong>: total project hours (optional)</li><li><strong>Revenue</strong>: always $0</li><li><strong>Billing model</strong>: none</li><li><strong>Use case</strong>: charity work, community projects, internal initiatives</li></ul><blockquote><p>&quot;Create project Community Website as Pro Bono&quot;</p></blockquote><hr><h3 id="retainer" tabindex="-1">Retainer <a class="header-anchor" href="#retainer" aria-label="Permalink to &quot;Retainer&quot;">​</a></h3><p>A standing engagement billed in serial periods rather than one lump contract. Creating a Retainer creates the parent engagement, and VERA immediately auto-creates its first billing period as a child of that parent — time is always logged to the active period, never to the parent itself.</p><ul><li><strong>Budget &amp; contract value</strong>: entered <strong>per period</strong>, not for the whole engagement — they flow onto the first period child, never the parent. A later period is added by asking for a new period (<code>create_retainer_period</code>), which by default inherits the previous period&#39;s terms unless told otherwise.</li><li><strong>The parent&#39;s page shows the engagement to date.</strong> The hours budget shown on a retainer&#39;s own page — in its Analytics and Allocation figures — is the <strong>sum across every closed and current period</strong>, so it sits against revenue, hours logged, and allocations, which cover the same closed-and-current set — a person&#39;s envelope on an upcoming (not-yet-started) period is likewise left out of the allocation total, so that claim is now genuinely true on both sides, not just the budget side. <strong>A period that hasn&#39;t started yet contributes nothing until it starts</strong> — its dates haven&#39;t arrived, so its budget isn&#39;t part of the engagement to date, and it joins the sum the day its window opens. (A budget drawn from only the current period, compared against figures from every period, would read as though the engagement were far more over-allocated than it is; a budget that already counted an upcoming period would overstate the engagement before that period had even begun.) Each period&#39;s own figure stays on the Periods card and on that period&#39;s own page.</li><li><strong>The on-course verdict is judged on the current period alone.</strong> A retainer with no shaped plan compares the hours recorded in its current period with that period&#39;s budget, in proportion to how much of its window has passed: a 10-day period on its 4th day is expected to have used 40% of its own budget. Other periods do not enter it, so an overrun this period can&#39;t be hidden by an underrun in an earlier one. The working line under the verdict names the period. Between periods, when none is current, VERA falls back to every finished period&#39;s full budget plus nothing for one that hasn&#39;t started. The Logged figure and Budget health above it still describe the whole engagement.</li><li><strong>A renewal that is due is on the page.</strong> When the current period ends within a week and no next period exists, the project&#39;s own page says so and links to the Periods card, where Re-up creates the next period. It is the same test as the renewal message VERA sends that morning.</li><li><strong>A period is a window, not a calendar month.</strong> A new period&#39;s start can be any real date, and its end is named explicitly or, left unstated, defaults to the last day of the start&#39;s month — so a plain monthly cadence needs no extra step, but a 10-day sprint of billing or a 6-week engagement is just as supported. Two periods on the same retainer can never claim the same day.</li><li><strong>A period&#39;s status tracks itself.</strong> VERA marks a period <code>planned</code> while its window is still ahead, <code>active</code> while today falls inside it, and <code>closed</code> once its window has passed — automatically, with no manual step. At most one period is ever <code>active</code> at a time.</li><li><strong>Revenue</strong>: <code>(hours_logged ÷ hours_budget) × contract_value</code>, computed <strong>per period</strong>, capped at 100%</li><li><strong>Billing model</strong>: percentage-of-completion, reset every period</li><li><strong>Deadline</strong>: none — a retainer&#39;s periods roll forward and the parent itself has no end date</li><li><strong>Renewal</strong>: parents carry a monthly renewal cadence by default, and VERA warns an owner when the latest period is about to run out with no successor lined up</li><li><strong>Vendor liabilities live on each period</strong>: when a vendor does a period&#39;s work for a fixed fee (a maintenance job farmed out the same way every month, say), the owner adds a vendor liability on that period&#39;s own page. It builds up evenly across the period&#39;s own window — nothing before the period opens, all of it by its last day — so it can be added to next month&#39;s period in advance. The vendor&#39;s hours count toward the period&#39;s hours, revenue and pace the same way a Fixed Price project counts them, and roll up into the retainer&#39;s own page. Re-up copies the previous period&#39;s active liabilities onto the new period, the same way it copies tasks; envelopes still don&#39;t carry over. The retainer&#39;s own page offers no Vendor liabilities card, because a retainer has periods instead of a deadline</li><li><strong>Use case</strong>: ongoing maintenance or standing monthly work with a recurring fee</li></ul><blockquote><p>&quot;Create project Acme Maintenance as Retainer, 40 hours and $6,000 for this month&quot;</p></blockquote><hr><hr><h2 id="project-fields" tabindex="-1">Project fields <a class="header-anchor" href="#project-fields" aria-label="Permalink to &quot;Project fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Who sets it</th></tr></thead><tbody><tr><td><code>name</code></td><td>Project name, unique per tenant</td><td>Owner</td></tr><tr><td><code>client</code></td><td>The client this project belongs to</td><td>Owner</td></tr><tr><td><code>type</code></td><td>One of T&amp;M, Fixed Price, Pro Bono, Internal, or Retainer</td><td>Owner</td></tr><tr><td><code>budget_hours</code></td><td>Total hours cap (or monthly for Retainer)</td><td>Owner via <code>set_project_budget</code></td></tr><tr><td><code>contract_value</code></td><td>Dollar amount (Fixed Price &amp; Agile sprints)</td><td>Owner</td></tr><tr><td><code>billing_rate</code></td><td>Hourly rate billed to client</td><td>Owner (in Projects Master)</td></tr><tr><td><code>is_billable</code></td><td>Whether hours generate revenue</td><td>Auto: false for Pro Bono, true otherwise</td></tr><tr><td><code>alert_threshold</code></td><td>% budget used before warning fires (default 80%)</td><td>Owner/Manager</td></tr><tr><td><code>start_date</code></td><td>The day the project starts; every schedule reading is measured from it</td><td>Set at creation (today unless named); owner or the project&#39;s PM via <code>set_project_start_date</code></td></tr><tr><td><code>deadline</code></td><td>Target delivery date</td><td>Owner via <code>set_project_deadline</code></td></tr><tr><td><code>pm_user_id</code></td><td>Assigned project manager</td><td>Owner via <code>assign_pm</code></td></tr><tr><td><code>project_category</code></td><td><code>client</code>, <code>internal</code>, <code>pto</code>, <code>sick</code>, <code>leave</code>, <code>time_off</code></td><td>Auto-set</td></tr><tr><td><code>status</code></td><td><code>active</code> or <code>inactive</code></td><td>Owner</td></tr></tbody></table><h3 id="start-date" tabindex="-1">Start date <a class="header-anchor" href="#start-date" aria-label="Permalink to &quot;Start date&quot;">​</a></h3><p>Every project has a start date. When a project is created without one, it starts today in the workspace&#39;s timezone, or on its deadline if that has already passed. An owner, or the manager who is the project&#39;s PM, can change it later from <strong>Edit project</strong>, with two limits:</p><ul><li>It can&#39;t be after the deadline (and the deadline can&#39;t be moved before it).</li><li>It can&#39;t be later than the first hours already recorded on the project, including its periods and sprints. Those hours show the work had already begun. Moving the start date earlier is always allowed.</li><li>Envelope windows sit inside the project&#39;s dates, so neither date can move inward past an active envelope&#39;s window, and on a Fixed Price project neither can move past a month that has a billing-schedule amount. Change or clear the window, or move the amount, first. Moving a date outward is always allowed.</li><li>Time can&#39;t be recorded, or moved, onto a day before a client project&#39;s start date. If work genuinely began earlier, move the start date earlier first. Time after the deadline is always accepted, and Internal projects (including PTO, Sick and Leave) accept any date.</li></ul><p>When VERA added this, each existing project&#39;s start date was moved back to its earliest recorded hours wherever those came first, so no project starts after work was recorded on it.</p><hr><h2 id="project-category-vs-type" tabindex="-1">Project category vs. type <a class="header-anchor" href="#project-category-vs-type" aria-label="Permalink to &quot;Project category vs. type&quot;">​</a></h2><p>These are two separate fields:</p><ul><li><strong>Type</strong> (<code>T&amp;M</code>, <code>Fixed Price</code>, etc.) governs <strong>billing and revenue recognition</strong></li><li><strong>Category</strong> (<code>client</code>, <code>internal</code>, <code>time_off</code>, etc.) governs <strong>how VERA treats the project in reports and queries</strong></li></ul><p>Internal projects (training, admin, hiring) should use the &quot;Internal&quot; client and <code>project_category = &quot;internal&quot;</code>. Selecting the <strong>Internal client</strong> automatically forces the project type to <strong>Internal</strong> — the type field is locked in the console form and coerced server-side. No budget, deadline, or billing rate is required for Internal projects.</p><p>PTO, Sick and Leave are created with every workspace. They can&#39;t be renamed, cancelled, closed or deleted. They are also evergreen: they have no status, start or end date, hours budget, billing or financials, and only their notes can be edited. Time can still be recorded against them as usual.</p><hr><h2 id="the-two-tier-budget-model" tabindex="-1">The two-tier budget model <a class="header-anchor" href="#the-two-tier-budget-model" aria-label="Permalink to &quot;The two-tier budget model&quot;">​</a></h2><p>There are two completely separate budget concepts. Do not confuse them.</p><p><strong>Tier 1 — Project total</strong>: <code>budget_hours</code> in the Projects sheet. This is the sold or contracted hours for the whole project. Set by Owner only via <code>set_project_budget</code>. Think of it as the pie.</p><p><strong>Tier 2 — Envelopes</strong>: rows in the Budgets sheet (<code>07. Budgets</code>). This is how Managers slice the pie — each team member gets a per-person envelope. The sum of all envelopes should not exceed Tier 1.</p><blockquote><p>A Manager asking &quot;how do I set the budget?&quot; wants to distribute hours to their team (Tier 2). The overall budget is set by the Owner (Tier 1) and is not the Manager&#39;s to change.</p></blockquote><p>See <a href="/reference/concepts/allocations.html">Envelopes</a> for the full picture.</p><hr><h2 id="retainer-periods-in-the-console" tabindex="-1">Retainer periods in the console <a class="header-anchor" href="#retainer-periods-in-the-console" aria-label="Permalink to &quot;Retainer periods in the console&quot;">​</a></h2><p>A Retainer&#39;s own page in the console (<code>/console/p/:id</code>) shows every period on a <strong>Periods</strong> card — dates, status, hours budget, contract value (owner/admin only), and hours logged so far — with the currently active period marked in words in its Status column, never by color alone. The hours budget in this page&#39;s Financials and Allocation figures is the total of the closed and current periods&#39; budgets — the engagement to date — not the active period&#39;s alone, and not a not-yet-started period&#39;s either; a period joins that total the day its own window opens. <strong>The parent&#39;s page carries no envelope list or Add-envelope control of its own</strong> — envelopes are added, cancelled, and reactivated only from a period&#39;s own staffing page, linked below.</p><p>Each period&#39;s dates on that card are a link to a page of its own, so a period can be staffed <strong>before it starts</strong>: a PM who rolls the engagement forward with Re-up (below) can open the brand-new, still-<code>planned</code> period immediately and add its envelopes right away, rather than waiting for its window to begin. That page shows the period&#39;s own dates, status, hours budget, contract value (owner/admin only), and its own list of active and cancelled envelopes — adding a new envelope, cancelling an existing one, and reactivating a cancelled one all happen here, scoped to that one period (editing an envelope&#39;s own hours or shape still happens on its own separate page, as it always has, linked from here the same way). When no period is currently active, the Add-envelope control on the parent&#39;s page — which used to target the active period automatically — no longer exists to hide; opening a period&#39;s own page and staffing it there works for a <code>planned</code> period exactly as it does for an <code>active</code> one.</p><p>A period still has no full project page of its own — its schedule and revenue stay rolled up onto the parent, so a page trying to report them for a period alone would report nothing (zero hours logged, in particular). The staffing page above is deliberately narrower than that: it never claims to compute schedule or revenue for the period. The parent&#39;s page remains where a retainer is understood end to end; the period&#39;s own page exists only to staff it.</p><h3 id="editing-a-period-and-re-up" tabindex="-1">Editing a period, and Re-up <a class="header-anchor" href="#editing-a-period-and-re-up" aria-label="Permalink to &quot;Editing a period, and Re-up&quot;">​</a></h3><p>An owner/admin, or the manager who is PM of record on the retainer, can correct a period&#39;s own terms — its hours budget, contract value (owner/admin only), and window — on the period&#39;s own page: open the period from its dates on the Periods card, change the fields, and press <strong>Save period</strong>, which returns to the same page. Hours can be fractional, to two decimal places (1.5, or 1.18 for 1h 11m), here and in every other hours field in the console. <strong>A <code>closed</code> period cannot be edited</strong>: its terms are history that revenue recognition has already consumed, so rewriting them would silently rewrite recognized revenue. A window can&#39;t be widened over a sibling period&#39;s own dates, and can&#39;t be shrunk past a date that already has time logged against it.</p><p>The Periods card also offers <strong>Re-up</strong> — a form prefilled with the previous period&#39;s terms, so rolling the engagement forward doesn&#39;t mean retyping numbers that mostly haven&#39;t changed. A plain monthly retainer rolls to the next calendar month; a retainer billed in some other cadence (a 10-day sprint of billing, say) rolls to the same length of time immediately following. The PM reviews the prefilled terms — changing anything that&#39;s been renegotiated — and submits to actually create the period; nothing is created just by opening the form.</p><p><strong>What carries over automatically, and what doesn&#39;t:</strong> the new period&#39;s enabled tasks are copied from the one before it, exactly as they are for any new period (see <a href="#project-lifecycle">Project lifecycle</a> below) — no manual step needed. <strong>Envelopes do not carry over.</strong> An envelope is a person&#39;s commitment to one specific period, so each new period starts with none, and the PM adds them fresh. VERA tells the PM both facts in the success message after Re-up.</p><h3 id="a-period-s-pm-can-differ-from-the-parent-s" tabindex="-1">A period&#39;s PM can differ from the parent&#39;s <a class="header-anchor" href="#a-period-s-pm-can-differ-from-the-parent-s" aria-label="Permalink to &quot;A period&#39;s PM can differ from the parent&#39;s&quot;">​</a></h3><p>A retainer runs for years, and the person managing it can change mid-engagement — sometimes for the whole retainer, sometimes for just one period. Each period&#39;s own page shows a <strong>Project Manager</strong> row, separate from the parent&#39;s, with a control to change it whenever the viewer is an owner or admin, or the manager who is PM of record on the parent (the same people who can edit that period&#39;s terms). A period with no PM of its own shows an em dash rather than the parent&#39;s name.</p><p>Reassigning the PM at the <strong>parent</strong> level rolls that change down onto every period that was simply going along with the parent&#39;s own PM. A period whose PM was <strong>deliberately set</strong> to someone else — from that period&#39;s own page — is left alone: it keeps its own PM through the next parent-level reassignment, rather than being silently overwritten. A <code>closed</code> period&#39;s PM can never be changed at all, on either surface — its terms are history, the same reason a closed period&#39;s hours budget and window can&#39;t be edited either.</p><p>The Periods card shows each period&#39;s own PM in a read-only <strong>PM</strong> column, so a retainer with several periods under different PMs is legible at a glance; the control that changes it lives on the period&#39;s own page.</p><p><strong>What this does not change:</strong> VERA&#39;s PM performance rollups still credit a period&#39;s hours, revenue, and cost to the <strong>parent&#39;s</strong> PM, not to whichever person is set as a period&#39;s own PM. Giving a period its own PM affects who can staff and manage it — it does not yet affect who VERA holds accountable for its numbers.</p><hr><h2 id="changing-a-project-s-type" tabindex="-1">Changing a project&#39;s type <a class="header-anchor" href="#changing-a-project-s-type" aria-label="Permalink to &quot;Changing a project&#39;s type&quot;">​</a></h2><p>An owner or admin can change a project between Fixed Price, T&amp;M, Pro Bono, Internal and Retainer from the project&#39;s page (Edit project, then Change project type), in any direction and as often as needed. Agile projects and the PTO, Sick and Leave projects cannot be converted.</p><p>Every hour already recorded stays on the project. Time recorded against a retainer period always stays with that period: when a retainer becomes another type its periods are kept as closed history and still count toward the project&#39;s hours, and when a project becomes a retainer, the time recorded directly on it moves into the retainer period whose dates cover it, or into one new period created by the change.</p><p>Revenue for the project&#39;s whole history is recalculated under the new type, so its numbers can change when you convert. The page says so before you confirm.</p><h2 id="duplicating-a-project" tabindex="-1">Duplicating a project <a class="header-anchor" href="#duplicating-a-project" aria-label="Permalink to &quot;Duplicating a project&quot;">​</a></h2><p>An owner or admin can make a new project from an existing one (Edit project, then Duplicate project), so a project set up like another doesn&#39;t have to be configured again by hand. You give the copy a name and a start date, and every other date moves forward by the same number of weeks: the deadline, each envelope&#39;s window and weekly plan, and a Fixed Price billing schedule (by the same number of months). The start date can&#39;t be in the past, and it is always a whole number of weeks from the original&#39;s, so a weekly plan lands on real weeks.</p><p>The copy takes the project&#39;s type, client, notes, project manager and target LER; its hours budget, contract value and billing rate; its enabled tasks; its active envelopes (same person, task, hours and label); and its active vendor liabilities. A retainer is copied from its last period: that period&#39;s terms, tasks, envelopes and liabilities become the new retainer&#39;s first period. Recorded time, time approvals, cancelled envelopes and liabilities, and a retainer&#39;s earlier periods are not copied. If any part can&#39;t be copied, the new project&#39;s page says which, so you can add it there.</p><h2 id="project-lifecycle" tabindex="-1">Project lifecycle <a class="header-anchor" href="#project-lifecycle" aria-label="Permalink to &quot;Project lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Budget set → PM assigned → Tasks enabled → Envelopes created</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                               Team logs time → Alerts fire if approaching budget</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                                    Completed / Inactive</span></span></code></pre></div><p>No formal state machine enforces this flow — VERA relies on the configured <code>status</code> field and the business rules in its system prompt.</p><p>For a <strong>Retainer or Agile</strong> project, &quot;Tasks enabled&quot; happens once per period, not once for the whole engagement — each new period is created with the same tasks already enabled that its source had, so it needs no manual step before it can receive envelopes. See <a href="/reference/concepts/allocations.html#a-new-period-inherits-enabled-tasks-automatically">A new period inherits enabled tasks automatically</a>.</p><hr><h2 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h2><p>Every project belongs to a client. If a client doesn&#39;t exist yet, VERA creates it automatically when a project is created.</p><p>Internal or overhead work belongs to the built-in &quot;Internal&quot; client. VERA creates &quot;Internal&quot; automatically when the first internal project is provisioned.</p><p>Financial rollups are client-aware: <code>get_client_summary</code> aggregates hours, budget, and spend across all of a client&#39;s projects.</p><p><em>Agile projects are documented above for reference — existing Agile projects remain fully operational, though new ones can no longer be created.</em></p>`,78)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
